@import url(../assets/css/at-ui.css);

main {
    height: 100px;
}

footer {
    display: none;
}

#app,
.map-btn-container {
    width: 100%;
    height: calc(100vh - 55px);
    min-width: 300px;
    margin: 0;
    padding: 0;
}

.ymap-container {
    height: 100%;
    position: relative;
}
</style>
